// Eduvelto — Internet Speed & Ping Test tool UI (28 Nov 2026, global batch item 2).
//
// Download and latency are measured against a test file hosted on OUR
// OWN site: public/speedtest.bin (4 MiB of random bytes, served by
// Cloudflare Pages — well under the 25 MiB single-asset limit).
// Upload posts generated bytes to OUR OWN endpoint, functions/
// speedtest-upload.js (a Cloudflare Pages Function that reads and
// discards the body, so the bytes travel to our origin and back).
//
// "Ping" is labelled honestly EVERYWHERE as browser fetch latency to
// our own origin — it is NOT ICMP ping, which a browser cannot do.
// Multiple samples are taken and the median is shown.
import { useRef, useState } from 'react';
import { useLanguage } from '../../i18n/LanguageContext';
import { Tiles, ToolSection, noteStyle, resultStyle, errorStyle } from './eduToolUi';

const TEST_FILE = '/speedtest.bin';
const UPLOAD_URL = '/speedtest-upload';
const UPLOAD_BYTES = 2 * 1024 * 1024;

interface Sample {
  label: string;
  mbps: number;
}

function median(values: number[]): number {
  if (values.length === 0) return 0;
  const sorted = [...values].sort((a, b) => a - b);
  const mid = Math.floor(sorted.length / 2);
  return sorted.length % 2 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2;
}

function randomBytes(n: number): Uint8Array {
  const buf = new Uint8Array(n);
  crypto.getRandomValues(buf);
  return buf;
}

export function InternetSpeedTestTool() {
  const { t } = useLanguage();
  const [running, setRunning] = useState(false);
  const [stage, setStage] = useState('');
  const [downSamples, setDownSamples] = useState<Sample[]>([]);
  const [upSamples, setUpSamples] = useState<Sample[]>([]);
  const [latencyMs, setLatencyMs] = useState<number[]>([]);
  const [error, setError] = useState('');
  const [done, setDone] = useState(false);
  const abortRef = useRef(false);

  async function measureDownload(): Promise<number> {
    const start = performance.now();
    const res = await fetch(`${TEST_FILE}?t=${Date.now()}`, { cache: 'no-store' });
    if (!res.ok) throw new Error(`download HTTP ${res.status}`);
    const reader = res.body?.getReader();
    if (!reader) {
      const buf = await res.arrayBuffer();
      const secs = (performance.now() - start) / 1000;
      return (buf.byteLength * 8) / secs / 1_000_000;
    }
    let bytes = 0;
    for (;;) {
      const { done: d, value } = await reader.read();
      if (d) break;
      bytes += value.length;
    }
    const secs = (performance.now() - start) / 1000;
    return (bytes * 8) / secs / 1_000_000;
  }

  async function measureUpload(): Promise<number> {
    const body = randomBytes(UPLOAD_BYTES);
    const start = performance.now();
    const res = await fetch(UPLOAD_URL, { method: 'POST', body: body as unknown as BodyInit, cache: 'no-store' });
    if (!res.ok) throw new Error(`upload HTTP ${res.status}`);
    await res.json().catch(() => undefined);
    const secs = (performance.now() - start) / 1000;
    return (UPLOAD_BYTES * 8) / secs / 1_000_000;
  }

  async function measureLatency(): Promise<number> {
    const start = performance.now();
    const res = await fetch(`${TEST_FILE}?ping=${Date.now()}`, {
      method: 'GET',
      headers: { Range: 'bytes=0-1023' },
      cache: 'no-store',
    });
    if (!res.ok && res.status !== 206) throw new Error(`latency HTTP ${res.status}`);
    await res.arrayBuffer().catch(() => undefined);
    return performance.now() - start;
  }

  async function run() {
    setRunning(true);
    setDone(false);
    setError('');
    setDownSamples([]);
    setUpSamples([]);
    setLatencyMs([]);
    abortRef.current = false;
    try {
      // Latency first: 5 small fetches to our own origin (browser fetch
      // latency — NOT ICMP ping; the UI says so).
      setStage(t({ bn: 'লেটেন্সি মাপা হচ্ছে…', en: 'Measuring latency…' }));
      const lat: number[] = [];
      for (let i = 0; i < 5; i++) {
        if (abortRef.current) return;
        lat.push(await measureLatency());
        setLatencyMs([...lat]);
      }
      // Download: 3 full fetches of our own 4 MiB test file.
      setStage(t({ bn: 'ডাউনলোড মাপা হচ্ছে…', en: 'Measuring download…' }));
      const down: Sample[] = [];
      for (let i = 0; i < 3; i++) {
        if (abortRef.current) return;
        const mbps = await measureDownload();
        down.push({ label: `${i + 1}`, mbps });
        setDownSamples([...down]);
      }
      // Upload: 2 posts of 2 MiB to our own upload endpoint.
      setStage(t({ bn: 'আপলোড মাপা হচ্ছে…', en: 'Measuring upload…' }));
      const up: Sample[] = [];
      for (let i = 0; i < 2; i++) {
        if (abortRef.current) return;
        const mbps = await measureUpload();
        up.push({ label: `${i + 1}`, mbps });
        setUpSamples([...up]);
      }
      setStage('');
      setDone(true);
    } catch (err) {
      setError(t({
        bn: 'গতি মাপা যায়নি — নেট সংযোগ দেখে আবার চেষ্টা করুন। (এই টেস্ট শুধু eduvelto.com-এর নিজের ফাইলের সাথে মাপে।)',
        en: 'The test could not run — check your connection and try again. (This test only measures against eduvelto.com’s own file.)',
      }));
      setStage('');
    } finally {
      setRunning(false);
    }
  }

  const downMed = median(downSamples.map((s) => s.mbps));
  const upMed = median(upSamples.map((s) => s.mbps));
  const latMed = median(latencyMs);

  return (
    <ToolSection id="internet-speed-test-title" titleBn="ইন্টারনেট স্পিড ও পিং টেস্ট" titleEn="Internet Speed & Ping Test"
      descBn="Eduvelto-র নিজের ফাইলের সাথে ডাউনলোড, আপলোড আর ফেচ লেটেন্সি মাপুন — কয়েকটি নমুনার মধ্যমা।"
      descEn="Measure download, upload and fetch latency against Eduvelto’s own file — the median of several samples.">
      <p style={noteStyle}>
        {t({
          bn: 'সৎ ব্যাখ্যা: “পিং” এখানে ব্রাউজারের ফেচ লেটেন্সি — eduvelto.com-এ ছোট একটি অনুরোধ পাঠিয়ে উত্তর আসতে কত মিলিসেকেন্ড লাগল। ব্রাউজার দিয়ে আসল ICMP পিং করা যায় না, তাই এটিকে ICMP পিং বলা হয়নি। ডাউনলোড মাপা হয় আমাদের নিজের ৪ MB ফাইল দিয়ে। আপলোড মাপতে ব্রাউজার নিজে তৈরি করা ডেটা পাঠায় — আপনার কোনো ফাইল আপলোড হয় না, সার্ভার ডেটা পড়ে ফেলে দেয়, কিছু সংরক্ষণ করে না।',
          en: 'Honest explanation: “ping” here is browser fetch latency — how many milliseconds a small request to eduvelto.com took to answer. A browser cannot do a real ICMP ping, so this is not called ICMP ping. Download is measured with our own 4 MB file. For upload, the browser sends data it generates itself — none of your files is uploaded, the server discards the data, and nothing is stored.',
        })}
      </p>
      <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap', marginTop: 12 }}>
        <button type="button" className="ev-btn ev-btn-primary" style={{ minHeight: 44 }} onClick={() => void run()} disabled={running}>
          {running ? t({ bn: 'মাপা হচ্ছে…', en: 'Testing…' }) : t({ bn: '▶ গতি মাপুন', en: '▶ Run speed test' })}
        </button>
        {running ? (
          <button type="button" className="ev-btn ev-btn-outline" style={{ minHeight: 44 }} onClick={() => { abortRef.current = true; }}>
            {t({ bn: 'বাতিল', en: 'Cancel' })}
          </button>
        ) : null}
      </div>
      {running && stage ? <p style={{ marginTop: 12 }} role="status">{stage}</p> : null}
      {error ? <p style={errorStyle} role="alert">{error}</p> : null}
      {(downSamples.length > 0 || upSamples.length > 0 || latencyMs.length > 0) ? (
        <div style={resultStyle} role="status">
          <Tiles items={[
            { label: t({ bn: 'ডাউনলোড (মধ্যমা)', en: 'Download (median)' }), value: downMed ? `${downMed.toFixed(1)} Mbps` : '—' },
            { label: t({ bn: 'আপলোড (মধ্যমা)', en: 'Upload (median)' }), value: upMed ? `${upMed.toFixed(1)} Mbps` : '—' },
            { label: t({ bn: 'ফেচ লেটেন্সি “পিং” (মধ্যমা)', en: 'Fetch latency “ping” (median)' }), value: latMed ? `${Math.round(latMed)} ms` : '—' },
          ]} />
          <p style={{ margin: '12px 0 0', fontSize: 14 }}>
            {t({ bn: 'ডাউনলোড নমুনা: ', en: 'Download samples: ' })}
            {downSamples.map((s) => `${s.mbps.toFixed(1)}`).join(', ') || '—'} Mbps
            {' · '}
            {t({ bn: 'আপলোড নমুনা: ', en: 'Upload samples: ' })}
            {upSamples.map((s) => `${s.mbps.toFixed(1)}`).join(', ') || '—'} Mbps
            {' · '}
            {t({ bn: 'লেটেন্সি নমুনা: ', en: 'Latency samples: ' })}
            {latencyMs.map((v) => `${Math.round(v)}`).join(', ') || '—'} ms
          </p>
          {done ? (
            <p style={noteStyle}>{t({ bn: 'ফলাফল আপনার ডিভাইস থেকে eduvelto.com পর্যন্ত পথের — অন্য সার্ভারের গতি আলাদা হতে পারে। ভিডিও দেখা বা গেম খেলার সময় আবার মাপলে ফল কম আসতে পারে।', en: 'These results are for the path from your device to eduvelto.com — other servers may differ. Re-testing while streaming or gaming will show lower numbers.' })}</p>
          ) : null}
        </div>
      ) : null}
    </ToolSection>
  );
}
